def analyze_pattern(inputs, outputs):
    """Analyze the pattern between inputs and outputs"""
    print("Analyzing pattern...")
    for i, (inp, out) in enumerate(zip(inputs, outputs)):
        print(f"Example {i}: '{inp}' -> '{out}'")
        if inp != out:
            # Find differences
            for j, (char_in, char_out) in enumerate(zip(inp, out)):
                if char_in != char_out:
                    print(f"  Position {j}: '{char_in}' -> '{char_out}'")
            # Check if output is longer
            if len(out) > len(inp):
                print(f"  Output is longer by {len(out) - len(inp)} characters")
            elif len(out) < len(inp):
                print(f"  Output is shorter by {len(inp) - len(out)} characters")

